
import Data  from 'fn/data.js';
import Event from 'sequence/modules/event.js';

// Define reactive options for Data proxies of events
Data.define(Event,               { enumerables: true, computed: ['beat', 'type'] });
Data.define(Event.ChordEvent,    { enumerables: true, computed: ['beat', 'root', 'extension', 'duration'] });
Data.define(Event.KeyEvent,      { enumerables: true, computed: ['beat', 'name', 'root'] });
Data.define(Event.MeterEvent,    { enumerables: true, computed: ['beat', 'rsid', 'divisor', 'divisions', 'beats', 'numerator', 'denominator', 'timesig'] });
Data.define(Event.NoteEvent,     { enumerables: true, computed: ['beat', 'pitch', 'number', 'gain', 'duration'] });
Data.define(Event.ControlEvent,  { enumerables: true, computed: ['beat', 'address', 'name', 'curve', 'value', 'duration'] });
Data.define(Event.RateEvent,     { enumerables: true, computed: ['beat', 'curve', 'value', 'duration'] });
Data.define(Event.SequenceEvent, { enumerables: true, computed: ['beat', 'identifier', 'TARGET', 'duration', 'transform', 'transforms'] });
Data.define(Event.TextEvent,     { enumerables: true, computed: ['beat', 'duration', 'text'] });
